content.content:
1	/**
2	 * ─── INTENÇÃO (certidão de nascimento) ───────────────────────────────────────
3	 * POR QUE EXISTE: corpo de PR que NARRA resultado sem COLAR a saída passou por prova três vezes
4	 *   numa semana na esteira de origem — "dumps SUBIRAM" com zero uploads no log; "idempotente" no
5	 *   changelog com o caminho idempotente saindo antes do bloco novo; LOC digitados diferentes dos
6	 *   reais. Em todos, prosa com verbo de resultado e nenhum bloco de saída; o CI verde não olha o
7	 *   corpo. Refino 2 (auditoria externa): UM bloco irrelevante lavava a seção inteira; aspas,
8	 *   título `##` e "funcionou — não inclui X" compravam isenção. Tudo fechado aqui.
9	 *
10	 * O QUE ESTA LIB DECIDE (funções PURAS — sem gh, sem fs): `julgarCorpo(body)` aplica 3 regras de
11	 *   FORMATO: (1) seção de prova com ≥1 bloco de saída NÃO-vazio; (2) seção "O que NÃO verifiquei"
12	 *   com ≥1 item; (3) cada frase com palavra-quente exige um bloco ADJACENTE (logo abaixo, com no
13	 *   máximo 1 linha de introdução; ou logo acima, sem prosa entre) e CADA BLOCO PROVA UMA FRASE SÓ.
14	 *   Negação isenta só o que vem depois dela na mesma oração. Citação vai em blockquote.
15	 *
16	 * O QUE NUNCA MAIS PODE PASSAR:
17	 *   1. frase-quente sem bloco de saída ao lado;
18	 *   2. corpo sem seção de prova com bloco — prova narrada não é prova;
19	 *   3. corpo sem "O que NÃO verifiquei" — limite omitido é teatro;
20	 *   4. bloco VAZIO contar como saída;
21	 *   5. UM bloco lavar a seção inteira;
22	 *   6. aspas, título `##` ou "— não inclui X" comprarem isenção.
23	 *
24	 * LIMITE CONHECIDO: julga FORMATO, não verdade — a verdade é da auditoria (passo 4), que
25	 *   re-executa. A lista de palavras-quentes é curta de propósito e cresce por incidente, com caso
26	 *   no self-test. Só `## ` abre seção. Identificador em crases sem espaço não é claim; frase é.
27	 * ─────────────────────────────────────────────────────────────────────────────
28	 */
29	
30	export const R = Object.freeze({
31	  CLAIM_SEM_BLOCO: 'CLAIM_SEM_BLOCO',
32	  SEM_BLOCO_DE_PROVA: 'SEM_BLOCO_DE_PROVA',
33	  SEM_NAO_VERIFIQUEI: 'SEM_NAO_VERIFIQUEI',
34	});
35	
36	export function normalizarTitulo(t) {
37	  return String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[*_`#]/g, '').trim();
38	}
39	
40	export const RE_SECAO_PROVA = /\b(prova|proof|refuta|evidenc)/;
41	export const RE_SECAO_NAO_VERIFIQUEI = /((nao|not)\s+(verifi|verified|checked|tested|testei)|limites?\s+(declarad|conhecid)|o que (nao|not)\s)/;
42	
43	export const RE_CLAIM = /\b(subiu|subiram|funcion(a|am|ou|aram|ando)|idempotente|backfill|aplicad[ao]s?\s+(em|na|no|nas|nos)\s+(prod\w*|staging|homolog\w*)|em\s+produ[cç][aã]o|(rodou|roda|rodaram)\s+com\s+sucesso|com\s+sucesso)\b/i;
44	const RE_CLAIM_G = new RegExp(RE_CLAIM.source, 'gi');
45	const RE_CLAIM_SUBSTANTIVO = /^(idempotente|backfill)$/i;
46	// "nunca funcionou" é a linha de regressão do fecho ("defeito que nunca funcionou") — declaração, não claim.
47	export const RE_NEGATIVA = /\b((n[aã]o|nunca)\s+(rod(ei|ado|ada|amos|ou)|verifi(quei|cado|cada|ca)|aplic[aá]vel|test(ei|ado|ada|a)|medi|medido|medida|cobre|pega|conserta|inclui|entra|faz|funcion\w*|subiu|subiram)|n\/a|nao\s+aplicavel)\b/i;
48	
49	export function ehDeclaracaoNegativa(linha) { return RE_NEGATIVA.test(String(linha || '')); }
50	
51	const RE_ORACAO = /\s[—–]\s|;\s|\.\s|\s-\s/;
52	
53	export function textoSemIdentificadores(texto) { return String(texto || '').replace(/`[^`\s]+`/g, ' '); }
54	
55	export function achaClaim(texto) {
56	  const t = textoSemIdentificadores(texto);
57	  if (/^\s*>/.test(t)) return null;
58	  if (/^\s*<!--[\s\S]*-->\s*$/.test(t)) return null;
59	  const oracoes = t.split(RE_ORACAO);
60	  for (let i = 0; i < oracoes.length; i++) {
61	    const oracao = oracoes[i];
62	    const neg = oracao.match(RE_NEGATIVA);
63	    const negProxima = (oracoes[i + 1] || '').match(RE_NEGATIVA);
64	    const proximaComecaNegando = Boolean(negProxima) && negProxima.index <= 12;
65	    RE_CLAIM_G.lastIndex = 0;
66	    let m;
67	    while ((m = RE_CLAIM_G.exec(oracao)) !== null) {
68	      if (neg && neg.index < m.index) continue;
69	      if (RE_CLAIM_SUBSTANTIVO.test(m[0]) && proximaComecaNegando) continue;
70	      return m[0];
71	    }
72	  }
73	  return null;
74	}
75	
76	export function extrairSecoes(body) {
77	  const linhas = String(body || '').split(/\r?\n/);
78	  const secoes = [{ titulo: '', inicio: 1, linhas: [], blocos: [] }];
79	  let cerca = null;
80	  let comentario = false; // dentro de <!-- ... --> multilinha (instrução de template): nem prosa, nem claim
81	  linhas.forEach((texto, i) => {
82	    const n = i + 1;
83	    const cur = secoes[secoes.length - 1];
84	    if (comentario) { if (/-->/.test(texto)) comentario = false; return; }
85	    if (/<!--/.test(texto) && !/-->/.test(texto)) { comentario = true; return; }
86	    const f = texto.match(/^\s*(```+|~~~+)/);
87	    if (f) {
88	      const ch = f[1][0];
89	      if (!cerca) { cerca = { char: ch, linhaInicio: n, linhas: [] }; return; }
90	      if (cerca.char === ch) { cur.blocos.push({ linhaInicio: cerca.linhaInicio, linhaFim: n, linhas: cerca.linhas }); cerca = null; return; }
91	    }
92	    if (cerca) { if (texto.trim() !== '') cerca.linhas.push(texto); return; }
93	    const h = texto.match(/^##\s+(.+?)\s*$/);
94	    if (h) { secoes.push({ titulo: h[1], inicio: n, linhas: [{ n, texto: h[1], titulo: true }], blocos: [] }); return; }
95	    cur.linhas.push({ n, texto });
96	  });
97	  if (cerca) secoes[secoes.length - 1].blocos.push({ linhaInicio: cerca.linhaInicio, linhaFim: linhas.length, linhas: cerca.linhas });
98	  return secoes;
99	}
100	
101	const temBlocoNaoVazio = (s) => s.blocos.some((b) => b.linhas.length > 0);
102	const ehComentarioHtml = (texto) => /^\s*<!--[\s\S]*-->\s*$/.test(texto);
103	// Marcador de lista sem texto ("-", "*", "- [ ]") é o template vazio, não um item.
104	const ehMarcadorVazio = (texto) => /^\s*([-*+]|\d+\.)(\s*\[\s*[xX ]?\s*\])?\s*$/.test(texto);
105	const ehProsa = (l) => !l.titulo && l.texto.trim() !== '' && !ehComentarioHtml(l.texto) && !ehMarcadorVazio(l.texto);
106	
107	export function blocoAdjacente(l, s, blocos) {
108	  const prosaEntre = (a, b) => s.linhas.filter((x) => x.n > a && x.n < b && ehProsa(x)).length;
109	  const abaixo = blocos.filter((b) => !b.usado && b.linhaInicio > l.n && prosaEntre(l.n, b.linhaInicio) <= 1).sort((a, b) => a.linhaInicio - b.linhaInicio)[0];
110	  if (abaixo) return abaixo;
111	  const acima = blocos.filter((b) => !b.usado && b.linhaFim < l.n && prosaEntre(b.linhaFim, l.n) === 0).sort((a, b) => b.linhaFim - a.linhaFim)[0];
112	  return acima || null;
113	}
114	
115	export function julgarCorpo(body) {
